_BY_SLUG = {lens.slug: lens for lens in LENSES}
ALWAYS_RUN_SLUG = "implementation"


def resolve_selection(selector_output: dict | None) -> tuple[list[Lens], str, dict]:
    """Map selector agent output to lenses.

    Returns (lenses, source, rationales). source is "selector" or
    "all-lenses-fallback". Unknown lens names are dropped; empty/invalid
    selection falls back to the full roster; the always-run lens is
    force-included.
    """
    selected: list[Lens] = []
    rationales: dict[str, str] = {}
    entries = (selector_output or {}).get("lenses") or []
    for entry in entries:
        lens = _BY_SLUG.get((entry or {}).get("name", ""))
        if lens is None or lens in selected:
            continue
        selected.append(lens)
        rationales[lens.slug] = entry.get("rationale", "")

    if not selected:
        return list(LENSES), "all-lenses-fallback", {}

    if _BY_SLUG[ALWAYS_RUN_SLUG] not in selected:
        selected.insert(0, _BY_SLUG[ALWAYS_RUN_SLUG])
        rationales[ALWAYS_RUN_SLUG] = "General correctness always runs."
    return selected, "selector", rationales


def resolve_dimensions(
    selector_output: dict | None, lens_count: int, max_agents: int
) -> list[dict]:
    """Dimensions from selector output, capped so lenses × dims <= max_agents.

    Default is one full-scope dimension. The selector may propose up to 3;
    excess dimensions are dropped (first kept) rather than dropping lenses.
    """
    default = [{"name": "full scope", "slug": "full-scope", "scope": {}}]
    proposed = (selector_output or {}).get("dimensions") or []
    dims: list[dict] = []
    seen_slugs: set[str] = set()
    for d in proposed[:3]:
        # scope keys are free-form ({"paths": [...]}, {"theme": ...}); the
        # optional shared_infrastructure flag alters agent prompts.
        if not (isinstance(d, dict) and d.get("name") and d.get("slug")):
            continue
        if d["slug"] in seen_slugs:
            # Duplicate slugs would race on the same output filename.
            continue
        seen_slugs.add(d["slug"])
        dims.append({"name": d["name"], "slug": d["slug"], "scope": d.get("scope", {})})
    dims = dims or default
    max_dims = max(1, max_agents // max(1, lens_count))
    return dims[:max_dims]
